"""Frobenius cycle-type classification and the full 2-part prediction.

Given an odd prime p and a separable depressed cubic f(x) = x^3 + A x + B over
F_p, this routine determines the cycle type of the Frobenius on the three
geometric roots of f, and from it predicts

  * the parity of #E(F_p)  (even  <=>  f has a rational root), and
  * the class of #E(F_p) modulo 4:
        type [1,1,1]  ->  0        (full rational 2-torsion)
        type [1]      ->  0 or 2, according as k = 3a^2 + A is a square or not
        type [3]      ->  odd
without ever counting points.
"""

from __future__ import annotations

from typing import Dict, List, Optional


def legendre(a: int, p: int) -> int:
    """Legendre symbol (a|p) in {-1, 0, 1}, for p an odd prime."""
    a %= p
    if a == 0:
        return 0
    return 1 if pow(a, (p - 1) // 2, p) == 1 else -1


def poly_mulmod(f: List[int], g: List[int], m: List[int], p: int) -> List[int]:
    """Multiply f by g modulo the monic polynomial m, over F_p."""
    out = [0] * (len(f) + len(g) - 1)
    for i, fi in enumerate(f):
        if fi:
            for j, gj in enumerate(g):
                out[i + j] = (out[i + j] + fi * gj) % p
    deg_m = len(m) - 1
    while len(out) > deg_m:
        c = out.pop()
        if c:
            shift = len(out) - deg_m
            for i, mi in enumerate(m[:-1]):
                out[shift + i] = (out[shift + i] - c * mi) % p
    while len(out) < deg_m:
        out.append(0)
    return out


def poly_gcd_degree(f: List[int], g: List[int], p: int) -> int:
    """Degree of gcd(f, g) over F_p (inputs as coefficient lists, low to high)."""

    def trim(h: List[int]) -> List[int]:
        while h and h[-1] % p == 0:
            h.pop()
        return h

    f, g = trim([c % p for c in f]), trim([c % p for c in g])
    while g:
        inv = pow(g[-1], p - 2, p)
        while len(f) >= len(g) and f:
            c = f[-1] * inv % p
            shift = len(f) - len(g)
            for i, gi in enumerate(g):
                f[shift + i] = (f[shift + i] - c * gi) % p
            trim(f)
        f, g = g, f
    return max(len(f) - 1, 0)


def rational_root_count(A: int, B: int, p: int) -> int:
    """Number of roots of x^3 + A x + B in F_p, via deg gcd(x^p - x, f).

    Cost: O(log p) multiplications of degree < 3 polynomials.
    """
    m = [B % p, A % p, 0, 1]  # f, monic of degree 3
    result: List[int] = [1, 0, 0]
    base: List[int] = [0, 1, 0]  # x
    e = p
    while e:
        if e & 1:
            result = poly_mulmod(result, base, m, p)
        base = poly_mulmod(base, base, m, p)
        e >>= 1
    xp_minus_x = [result[0] % p, (result[1] - 1) % p, result[2] % p]
    return poly_gcd_degree(m[:], xp_minus_x, p)


def analyse(A: int, B: int, p: int) -> Dict[str, object]:
    """Full 2-part analysis of y^2 = x^3 + A x + B over F_p."""
    disc = (-4 * A**3 - 27 * B**2) % p
    if p == 2 or disc == 0:
        raise ValueError("need an odd prime of good reduction")
    r = rational_root_count(A, B, p)
    cycle_type = {3: "[1,1,1]", 1: "[1]", 0: "[3]"}[r]
    root: Optional[int] = None
    mod4: Optional[int] = None
    if r >= 1:
        root = next(x for x in range(p) if (x * x % p * x + A * x + B) % p == 0)
    if r == 3:
        mod4 = 0
    elif r == 1:
        k = (3 * root * root + A) % p  # type: ignore[operator]
        mod4 = 0 if legendre(k, p) == 1 else 2
    return {
        "p": p,
        "discriminant mod p": disc,
        "rational roots": r,
        "Frobenius cycle type": cycle_type,
        "legendre(disc, p)": legendre(-4 * A**3 - 27 * B**2, p),
        "order is even": r > 0,
        "order mod 4": mod4 if r > 0 else "odd",
        "witness root": root,
    }


if __name__ == "__main__":
    for prime in (11, 13, 23, 29, 41, 47, 101, 1009):
        print(analyse(1, 1, prime))

"""Exact and empirical analysis of the residue-to-parity information channel.

Two channels are compared.

  SINGLE PRIME.   Observable X' = (p | 31); event Y' = [2 | #E0(F_p)].
                  P(Y'|X'=-1) = 1 (a theorem), P(Y'|X'=+1) = 1/3 (Chebotarev).
                  Capacity  H(2/3) - (1/2) H(1/3) = 0.4591 bits.

  SEMIPRIME.      Observable X = (N | 31) for N = p q; event
                  Y = [2 | #E0(F_p)] OR [2 | #E0(F_q)].
                  P(Y|X=-1) = 1 (a theorem), P(Y|X=+1) = 7/9.
                  Capacity  H(8/9) - (1/2) H(7/9) = 0.1212 bits.

The gap between the two numbers is the price of symmetry: the Jacobi symbol is a
product over the hidden primes, so it can only report symmetric functions of the
pair (p, q).  The routine also estimates the ASYMMETRIC channel
X -> [2 | #E0(F_p)] for the smaller factor p, which is provably zero under the
exchangeable model and is measured at the estimator noise floor.

Complexity: the exact constants are closed-form; the empirical estimate costs
one cubic-root test per prime (O(log p) modular operations with the polynomial
method, O(p) with naive enumeration) and O(1) per sampled semiprime.
"""

from __future__ import annotations

import math
import random
from typing import Dict, List, Tuple


def binary_entropy(t: float) -> float:
    """H(t) = -t log2 t - (1-t) log2(1-t), in bits."""
    if t <= 0.0 or t >= 1.0:
        return 0.0
    return -t * math.log2(t) - (1 - t) * math.log2(1 - t)


def exact_capacities() -> Dict[str, float]:
    """Closed-form mutual information of the two channels, in bits."""
    return {
        "single prime": binary_entropy(2 / 3) - 0.5 * binary_entropy(1 / 3),
        "semiprime (symmetric)": binary_entropy(8 / 9) - 0.5 * binary_entropy(7 / 9),
        "semiprime (asymmetric)": 0.0,
    }


def mutual_information(pairs: List[Tuple[int, int]]) -> float:
    """Plug-in estimate of I(X;Y) in bits from an empirical sample."""
    n = len(pairs)
    joint: Dict[Tuple[int, int], int] = {}
    px: Dict[int, int] = {}
    py: Dict[int, int] = {}
    for x, y in pairs:
        joint[(x, y)] = joint.get((x, y), 0) + 1
        px[x] = px.get(x, 0) + 1
        py[y] = py.get(y, 0) + 1
    return sum(
        (c / n) * math.log2((c / n) / ((px[x] / n) * (py[y] / n)))
        for (x, y), c in joint.items()
    )


def jacobi(a: int, n: int) -> int:
    """Jacobi symbol (a|n) for odd n > 0."""
    a %= n
    result = 1
    while a:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a %= n
    return result if n == 1 else 0


def primes_up_to(n: int) -> List[int]:
    sieve = bytearray([1]) * (n + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            sieve[i * i :: i] = bytearray(len(sieve[i * i :: i]))
    return [i for i in range(n + 1) if sieve[i]]


def has_rational_root(p: int, A: int = 1, B: int = 1) -> bool:
    """Whether x^3 + A x + B has a root mod p -- equivalently 2 | #E(F_p)."""
    return any((x * x % p * x + A * x + B) % p == 0 for x in range(p))


def empirical_channel(
    prime_bound: int = 20000, samples: int = 20000, seed: int = 404
) -> Dict[str, float]:
    """Measure both channels on random semiprimes built from primes < bound."""
    primes = [p for p in primes_up_to(prime_bound) if p not in (2, 31)]
    even = {p: has_rational_root(p) for p in primes}
    rng = random.Random(seed)
    sym: List[Tuple[int, int]] = []
    asym: List[Tuple[int, int]] = []
    residue: List[Tuple[int, int]] = []
    single: List[Tuple[int, int]] = []
    for _ in range(samples):
        p, q = rng.choice(primes), rng.choice(primes)
        if p == q:
            continue
        p, q = min(p, q), max(p, q)
        N = p * q
        x = jacobi(N, 31)
        sym.append((x, int(even[p] or even[q])))
        asym.append((x, int(even[p])))
        residue.append((N % 31, int(even[p] or even[q])))
        single.append((jacobi(p, 31), int(even[p])))
    return {
        "I(jacobi(N,31); OR)": mutual_information(sym),
        "I(N mod 31; OR)": mutual_information(residue),
        "I(jacobi(N,31); even at smaller factor)": mutual_information(asym),
        "I(jacobi(p,31); even at p)": mutual_information(single),
    }


if __name__ == "__main__":
    print("exact capacities (bits):")
    for name, value in exact_capacities().items():
        print(f"  {name:<26} {value:.4f}")
    print("empirical (bits):")
    for name, value in empirical_channel().items():
        print(f"  {name:<42} {value:.4f}")
